})()

(async () => {
  // Poll: the interrupt settles the run, the flush sends the queue, and the
  // host's next run reports the prompt it received — three hand-offs, none of
  // which the click itself can wait on.
  const deadline = Date.now() + 12000;
  const rows = () => [...document.querySelectorAll('[data-message-id]')];
  while (Date.now() < deadline) {
    const merged = rows().filter(row => (row.innerText || '').includes('顺便把图例移到右下角'));
    if (merged.length > 1) throw new Error('the two drafts left as separate messages');
    if (merged.length === 1) {
      const text = merged[0].innerText || '';
      if (!text.includes('再把图注也改成中文')) throw new Error('the second draft did not travel with the queue: ' + text.slice(0, 160));
      if (document.querySelector('[data-send-queue]')) throw new Error('the queue outlived the interrupt');
      return 'one message carried both: ' + text.replace(/\s+/g, ' ').slice(0, 120);
    }
    await new Promise(r => setTimeout(r, 250));
  }
  throw new Error('the queue never left the composer');
})()

